import {validateEventCondition,eventConditionMet,eventConditionLabel} from './scenario-events.js?v=subway-neighbors-1';
import {expandScenarioText} from './scenario-text.js?v=subway-neighbors-1';
import {escapeAnnouncement} from './scenario-announcements.js?v=subway-neighbors-1';
export function validateScenarioRanks(value,size=48){if(value===undefined)return[];if(!Array.isArray(value)||value.length>4)throw Error('Choose at most four scenario ranks.');const names=new Set();return Array.from(value,r=>{if(!r||typeof r.name!=='string'||!r.name.trim()||r.name.length>60||/[\x00-\x1f]/.test(r.name)||names.has(r.name.trim().toLowerCase())||!['won','lost','either'].includes(r.outcome)||typeof r.message!=='string'||r.message.length>500||/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(r.message))throw Error('Give each rank a distinct name, an outcome and a message up to 500 characters.');names.add(r.name.trim().toLowerCase());return{name:r.name.trim(),outcome:r.outcome,message:r.message.trim(),condition:validateEventCondition(r.condition,size)};});}
export function awardScenarioRank(c){const s=c.scenario;if(s.id!=='custom')return;const index=s.definition.ranks.findIndex(r=>(r.outcome==='either'||r.outcome===s.status)&&eventConditionMet(c,r.condition));if(index<0){s.rankOutcome=null;return;}const rank=s.definition.ranks[index];s.rank=rank.name;s.rankOutcome={index,message:expandScenarioText(rank.message,c)};}
export function validateRankOutcome(value,definition,status,rank){if(value===undefined||value===null){if(status!=='playing'&&!['Distinguished mayor','Mayor','Try again'].includes(rank))throw Error('Missing awarded scenario rank.');return null;}const r=definition.ranks[value.index];if(status==='playing'||!Number.isInteger(value.index)||!r||r.name!==rank||(r.outcome!=='either'&&r.outcome!==status)||typeof value.message!=='string'||value.message.length>4000||/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(value.message))throw Error('Invalid awarded scenario rank.');return{index:value.index,message:value.message};}
export function scenarioRanksReport(c){const s=c.scenario;if(s?.id!=='custom'||!s.definition.ranks?.length)return'';const awarded=s.rankOutcome;return `${awarded?`<h3>${escapeAnnouncement(s.rank)}</h3><p style="white-space:pre-wrap">${escapeAnnouncement(awarded.message)}</p>`:''}<details><summary>Available scenario ranks</summary><p>The first matching rank in this list is awarded when the challenge ends. Conditions are evaluated then; the awarded rank and message remain fixed. Ranks do not change whether the challenge is won or lost.</p><ol>${s.definition.ranks.map(r=>`<li><strong>${escapeAnnouncement(r.name)}</strong> · ${r.outcome==='either'?'Any outcome':r.outcome==='won'?'Victory':'Deadline loss'}${r.condition?' · '+escapeAnnouncement(eventConditionLabel(r.condition)):' · No additional condition'}</li>`).join('')}</ol><p>If none match, the standard completion-time rank applies.</p></details>`;}
